const fs = require('fs');
const path = require('path');

const BASE_DIR = '/home/user/n8n-files/projects';

const input = $input.first().json;
const projectId = String(input.query?.project_id || '').replace(/[^a-zA-Z0-9_-]/g, '');
const subPath = String(input.query?.path || '').replace(/\.\./g, '').replace(/[^a-zA-Z0-9/_.-]/g, '_');
const fileName = String(input.query?.file || '').replace(/\.\./g, '').replace(/[\/]/g, '').replace(/[^a-zA-Z0-9._-]/g, '_');

if (!projectId || !subPath || !fileName) {
  throw new Error('project_id, path en file zijn verplicht.');
}

const filePath = path.join(BASE_DIR, projectId, subPath, fileName);

if (!fs.existsSync(filePath)) {
  throw new Error('Bestand niet gevonden.');
}

// Detecteer MIME type
const ext = path.extname(fileName).toLowerCase();
const mimeTypes = {
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.png': 'image/png',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
  '.heic': 'image/heic',
  '.bmp': 'image/bmp'
};
const mimeType = mimeTypes[ext] || 'application/octet-stream';

// Lees bestand als buffer
const fileBuffer = fs.readFileSync(filePath);
const base64 = fileBuffer.toString('base64');

return [{
  json: {},
  binary: {
    data: {
      data: base64,
      mimeType: mimeType,
      fileName: fileName
    }
  }
}];
